\label{thm:Mineyev} Let $\Gamma$ be a finitely generated word hyperbolic group. 

Then there exists a proper hyperbolic metric space 
	$F\Gamma$ with the following properties\/{\em :}
	\begin{itemize} 
		\item[(i)] $\Gamma\times{\mathbb{R}}\times{\mathbb Z}/2{\mathbb Z}$ acts on $F\Gamma$.
		\item[(ii)] The $\Gamma\times {\mathbb Z}/2{\mathbb Z}$-action is isometric.
		\item[(iii)] Every orbit $\Gamma\rightarrow F\Gamma$ is a quasi-isometry.                                                                     
		\item[(iv)] The ${\mathbb{R}}$-action is free, and every orbit ${\mathbb{R}} \rightarrow F\Gamma$ is a quasi-isometric embedding. 
		The induced map $F\Gamma/{\mathbb{R}} \rightarrow \partial_\infty^{(2)}\hat \Gamma$ is a homeomorphism.
	\end{itemize}

\label{lem:Equiv} 
	Let a finitely generated discrete affine transformation group $G$ have  linear holonomy representation $\rho:G \rightarrow {\mathsf{GL}}(n, {\mathbb{R}})$.


	Then the following are equivalent\/{\em :} 
	\begin{itemize} 
	\item  $\rho$ is $P$-Anosov in the Gu\'eritaud-Guichard-Kassel-Wienhard sense \cite{GGKW17ii}
	for some parabolic group $P = P_\theta$ for an index set $\theta$ containing  $k$
	and $n-k$. 












	\item  $\rho$ is a $k$-dominated representation 

	for $1 \leq k \leq n/2$. 
	\end{itemize}

\label{cor:main2-p2} 
	A closed complete affine manifold $M^n$, $n \geq 3$, cannot have a $P$-Anosov linear holonomy group
	for a parabolic subgroup $P$ of ${\mathsf{GL}}(n, {\mathbb{R}})$.

\label{lem:geotwoends-p2} 
A geodesic in a Gromov hyperbolic space $X$  has two distinct endpoints in 
$\partial_\infty X$.

\label{lem:nonasym-p2} 
	Given two rays $m$ and $m'$ ending at $p$ and $q$ in $\partial_\infty \hat M$. If $p\ne q$, then $d_{\hat M}(m(t), m'(t))\rightarrow \infty$ 
	as $t \rightarrow \infty$.

\label{lem:Crough-p2} 
	Let $C'$ be the quasi-geodesic constant. Let $x\in \hat M$. 
	Then $f_q(x)$ is a $C'$-roughly continuous function of $q$.
